package de.corporate.lc.messaging.service;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import de.corporate.lc.messaging.domain.OutboxMessage;import de.corporate.lc.messaging.repository.OutboxMessageRepository;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.time.LocalDateTime;import java.util.Map;
@Service public class OutboxService{private final OutboxMessageRepository repo;private final ObjectMapper json;private final MessagePublisher publisher;public OutboxService(OutboxMessageRepository repo,ObjectMapper json,MessagePublisher publisher){this.repo=repo;this.json=json;this.publisher=publisher;}@Transactional public void enqueue(String topic,Object key,Object payload){OutboxMessage message=new OutboxMessage();message.setTopic(topic);message.setMessageKey(key==null?null:String.valueOf(key));try{message.setPayload(json.writeValueAsString(payload));}catch(JsonProcessingException ex){throw new IllegalArgumentException("Integrationsereignis konnte nicht serialisiert werden.",ex);}repo.save(message);}@Scheduled(fixedDelayString="${app.messaging.outbox-interval-ms:5000}")public void dispatch(){for(OutboxMessage message:repo.findTop50ByStatusAndNextAttemptAtLessThanEqualOrderByCreatedAt("PENDING",LocalDateTime.now()))publish(message);}@Transactional(propagation=Propagation.REQUIRES_NEW)public void publish(OutboxMessage message){try{publisher.publish(message.getTopic(),message.getMessageKey(),message.getPayload());message.setStatus("PUBLISHED");message.setPublishedAt(LocalDateTime.now());message.setLastError(null);}catch(RuntimeException ex){message.setAttempts(message.getAttempts()+1);message.setNextAttemptAt(LocalDateTime.now().plusSeconds(Math.min(300,1L<<Math.min(message.getAttempts(),8))));String error=ex.getMessage()==null?ex.getClass().getSimpleName():ex.getMessage();message.setLastError(error.substring(0,Math.min(1000,error.length())));}repo.save(message);}public Map<String,Object> status(){return Map.of("provider",publisher.provider(),"pending",repo.findTop50ByStatusAndNextAttemptAtLessThanEqualOrderByCreatedAt("PENDING",LocalDateTime.now()).size());}}
